 const login=async()=>{try{setLoginError("");let found:User|undefined;if(supabaseConfigured){const profile=await claimStaffAccess(loginCode),visibleProfiles=await loadVisibleProfiles();const mapped:User[]=visibleProfiles.map((p:any)=>({name:p.full_name,short:p.short_name,initials:p.initials,role:p.role==="manager"?"Manager":p.role==="assistant"?"Assistant":"Agent",code:"",email:p.email||"",cellphone:p.cellphone||"",profileId:p.id,teamId:p.team_id}));found=mapped.find(u=>u.profileId===profile.profile_id)||{name:profile.full_name,short:profile.short_name,initials:profile.initials,role:profile.role==="manager"?"Manager":profile.role==="assistant"?"Assistant":"Agent",code:"",email:"",cellphone:"",profileId:profile.profile_id,teamId:profile.team_id};setUsers(mapped);localStorage.setItem("pg-users",JSON.stringify(mapped));const remote=await loadSharedRecords();if(remote.length){setTasks(remote.filter(r=>r.record_type==="task").map(r=>r.payload as unknown as Task));setAppointments(remote.filter(r=>r.record_type==="appointment").map(r=>r.payload as unknown as Appointment));setMaintenance(remote.filter(r=>r.record_type==="maintenance").map(r=>r.payload as unknown as Maintenance));setRenewals(remote.filter(r=>r.record_type==="renewal").map(r=>r.payload as unknown as LeaseRenewal));setNewLeases(remote.filter(r=>r.record_type==="new_lease").map(r=>r.payload as unknown as NewLease))}else{const teamId=found.teamId!,profileId=found.profileId!,uploads=[...tasks.map(x=>saveSharedRecord("task",teamId,profileId,x as any)),...appointments.map(x=>saveSharedRecord("appointment",teamId,profileId,x as any)),...maintenance.map(x=>saveSharedRecord("maintenance",teamId,profileId,x as any)),...renewals.map(x=>saveSharedRecord("renewal",teamId,profileId,x as any)),...newLeases.map(x=>saveSharedRecord("new_lease",teamId,profileId,x as any))];await Promise.all(uploads)}}else found=users.find(u=>u.code===loginCode);if(!found){setLoginError("That access code is not recognised.");return}const key=`pg-greeting-date-${found.name}`,today=new Date().toLocaleDateString("en-CA"),isFirst=localStorage.getItem(key)!==today;localStorage.setItem("pg-user",found.name);localStorage.setItem(key,today);setCurrent(found);setShowDailyGreeting(isFirst);setView("personal")}catch(error:any){setLoginError(error?.message?.includes("recognised")?"That access code is not recognised.":"Could not connect securely. Please try again.")}};
