function TaskDialog({dialog,setDialog,form,setForm,addTask,users}:any){return <Dialog open={dialog} onOpenChange={setDialog}><DialogTrigger asChild><Button className="add-button"><Plus/>Add task</Button></DialogTrigger><DialogContent className="task-dialog compact-property-dialog compact-task-dialog"><DialogHeader><DialogTitle>Create a task</DialogTitle><DialogDescription>Assign the task to yourself or the other person connected to your profile.</DialogDescription></DialogHeader><div className="form-grid"><label>Task<input autoFocus value={form.title} onChange={(e:any)=>setForm({...form,title:e.target.value})} placeholder="e.g. Follow up tenant application"/></label><label>Property<input value={form.property} onChange={(e:any)=>setForm({...form,property:e.target.value})} placeholder="Address or property name"/></label><label className="notes-field">Task notes<textarea value={form.notes} onChange={(e:any)=>setForm({...form,notes:e.target.value})} placeholder="Add instructions, contact details or follow-up notes..."/></label><label>Assign to<select value={form.assignee} onChange={(e:any)=>setForm({...form,assignee:e.target.value})}>{users.map((u:User)=><option key={u.name} value={u.short}>{u.name}</option>)}</select></label><label>Due<select value={form.due} onChange={(e:any)=>setForm({...form,due:e.target.value})}><option>Today</option><option>Tomorrow</option><option>This week</option></select></label><label>Time<input type="time" value={form.time} onChange={(e:any)=>setForm({...form,time:e.target.value})}/></label><label>Priority<select value={form.priority} onChange={(e:any)=>setForm({...form,priority:e.target.value})}><option>Normal</option><option>High</option><option>Urgent</option></select></label></div><DialogFooter><Button variant="outline" onClick={()=>setDialog(false)}>Cancel</Button><Button className="add-button" onClick={addTask}>Create task</Button></DialogFooter></DialogContent></Dialog>}
function AppointmentDialog({open,setOpen,form,setForm,addAppointment,showTrigger=true}:any){return <Dialog open={open} onOpenChange={setOpen}>{showTrigger&&<DialogTrigger asChild><Button className="add-button"><Plus/>Add appointment</Button></DialogTrigger>}<DialogContent className="task-dialog"><DialogHeader><DialogTitle>Add a meeting or appointment</DialogTitle><DialogDescription>Choose the exact date and add it to Google Calendar.</DialogDescription></DialogHeader><div className="form-grid appointment-form"><label>Meeting or appointment<input autoFocus value={form.title} onChange={(e:any)=>setForm({...form,title:e.target.value})} placeholder="e.g. Tenant viewing"/></label><label>Location or property<input value={form.place} onChange={(e:any)=>setForm({...form,place:e.target.value})} placeholder="Address, office or online"/></label><label>Date<input type="date" value={form.date} min={dateKey(0)} onChange={(e:any)=>setForm({...form,date:e.target.value})}/></label><label>Time<input type="time" value={form.time} onChange={(e:any)=>setForm({...form,time:e.target.value})}/></label><label>Duration<select value={form.duration} onChange={(e:any)=>setForm({...form,duration:e.target.value})}><option>30 minutes</option><option>60 minutes</option><option>90 minutes</option><option>120 minutes</option></select></label><label className="meeting-link-field">Zoom or Microsoft Teams link<input type="url" value={form.meetingLink} onChange={(e:any)=>setForm({...form,meetingLink:e.target.value})} placeholder="https://zoom.us/... or https://teams.microsoft.com/..."/></label></div><DialogFooter><Button variant="outline" onClick={()=>setOpen(false)}>Cancel</Button><Button className="add-button" onClick={addAppointment}>Add to Google Calendar</Button></DialogFooter></DialogContent></Dialog>}
